const input = $input.first().json;
const body = input.body || input;

return [{
  json: {
    course_title: body.course_title || '',
    module_title: body.module_title || '',
    module_number: body.module_number || 1,
    module_objectives: body.module_objectives || body.learning_objectives || [],
    module_lessons_summary: body.module_lessons_summary || body.lessons_summary || '',
    questions_count: body.questions_count || 5,
    pass_score: body.pass_score || 70,
    level: body.level || 'debutant'
  }
}];

const response = $input.first().json;
const meta = $('Normaliser — Input').first().json;

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing quiz: ' + e.message);
}

const quiz = parsed.quiz || {};
const exercise = parsed.practical_exercise || {};

// Build quiz as a Lesson of type 'quiz' matching the Formation data model
const quizLesson = {
  id: crypto.randomUUID(),
  title: quiz.title || `Quiz — Module ${meta.module_number}`,
  type: 'quiz',
  duration: `${Math.ceil((quiz.questions || []).length * 2)} min`,
  content: JSON.stringify({
    pass_score_percent: quiz.pass_score_percent || 70,
    shuffle_questions: quiz.shuffle_questions || true,
    questions: quiz.questions || []
  }),
  order: 99,
  isFree: false
};

// Build exercise as a Lesson of type 'mission'
const missionLesson = {
  id: crypto.randomUUID(),
  title: exercise.title || `Exercice pratique — Module ${meta.module_number}`,
  type: 'mission',
  duration: `${exercise.estimated_duration_minutes || 30} min`,
  content: JSON.stringify({
    instructions: exercise.instructions || '',
    context_local: exercise.context_local || '',
    deliverable: exercise.deliverable || '',
    evaluation_rubric: exercise.evaluation_rubric || []
  }),
  order: 98,
  isFree: false
};

return [{
  json: {
    quiz_lesson: quizLesson,
    mission_lesson: missionLesson,
    course_title: meta.course_title,
    module_number: meta.module_number,
    module_title: meta.module_title,
    questions_count: (quiz.questions || []).length
  }
}];
